                "n": "مقام اول در زیارت دو امام معصوم حضرت هادی و حضرت حسن عسگری صلوات اللّه علیهما. هرگاه‌ان شاء اللّه بر سُرَّمَن رَای وارد شدی، و خواستی آن دو امام همام (عَلَیهِمَا السَّلَامُ) را زیارت کنی، غسل کن، و پس از رعایت آداب ورود به حرم‌های شریفه، تا در حرم مطهر با آرامش و وقار روانه شو، و اذن دخول عامّی را که در اوایل این باب ذکر شد بخوان، آنگاه وارد حرم مطهر شو، و آن دو بزرگوار را به این عبارت که صحیح‌ترین زیارات است زیارت کن"
