                "f": "و صدّیقان، و درودهای پاک و پاکیزه در آنچه می‌آید و می‌رود، بر تو باد‌ای مسلم بن عقیل بن ابی‌طالب و رحمت و برکات خدا بر تو باد، شهادت می‌دهم که تو نماز را بپا داشتی، و پرداختی زکات را، و امر به معروف و نهی از منکر کردی، و در راه خدا جهاد نمودی جهادی شایسته و به راه و روش مجاهدان در راه او کشته شدی، تا خدای عزّ و جل را درحالی‌که از تو راضی بود، ملاقات نمودی و شهادت می‌دهم که تو به عهد خدا وفا کردی، و جانت را در راه یاری حجّت خدا و پسر حجّت خدا دادی تا مرگ تو دررسید، شهادت می‌دهم برای تو، به تسلیم و وفاداری و خیرخواهی، برای یادگار نبیّ مرسل، و نوه برگزیده، و راهنمای عالم، و جانشین تبلیغ‌کننده و ستمدیده حق غارت‌شده، خدایا پاداشت دهد از جانب رسولش و امیر مؤمنان و حسن و حسین بهترین پاداش به خاطر آنکه صبر کردی و کارت را به حساب حق گذاشتی و کمک کردی. چه خوب است سرانجام سرای آخرت، خدا لعنت کند کسی که تو را کشت، و کسی که به کشتنت فرمان داد، و کسی که به تو ستم کرد، و کسی که بر تو دروغ بست،"
